import{programmes,stages,intakeOptions,isAdult,requirements,validate,allErrors,safeFile,csvCell}from'./domain.js';
const $=s=>document.querySelector(s),root=$('#app');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',file:'M6 3h8l4 4v14H6z M14 3v5h4 M9 12h6 M9 16h6',folder:'M3 7h7l2 2h9v11H3z M3 7V4h7l2 3',chat:'M4 4h16v12H9l-5 4z M8 8h8 M8 12h5',bell:'M6 17V9a6 6 0 0 1 12 0v8l2 2H4z M10 22h4',help:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20 M9 8a3 3 0 1 1 4 3l-1 2 M12 17h.01',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M14 7l5 5-5 5',down:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',search:'M10 18a8 8 0 1 0 0-16 8 8 0 0 0 0 16 M16 16l6 6',check:'M5 12l4 4L19 6',clock:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20 M12 6v6l4 2',cap:'M2 8l10-5 10 5-10 5z M6 11v7c3 3 9 3 12 0v-7 M22 8v9',back:'M19 12H5 M10 7l-5 5 5 5',logout:'M9 4H4v16h5 M12 12h9 M17 8l4 4-4 4'};
const icon=n=>'<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="'+(icons[n]||icons.file)+'"/></svg>';
const fmt=d=>new Date(d).toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'});
const name=a=>[a.firstName,a.lastName].filter(Boolean).join(' ')||'Untitled draft';
const initials=a=>(a.firstName?.[0]||'')+(a.lastName?.[0]||'');
const short=p=>p.replace('BSc ','').replace('BEng ','');
const badge=s=>'<span class="badge '+(/Pending|Incomplete/.test(s)?'gold':/Offer|Plan Issued/.test(s)?'purple':/Eligible|Paid|Enrolled/.test(s)?'green':/Draft/.test(s)?'gray':'')+'">'+esc(s)+'</span>';
let db,records=[],messages=[],view='overview',selected=null,detailTab='overview',form=null,step=0,errors=[],savedAt='',agentSession=sessionStorage.getItem('rcl-agent-preview')==='yes',search='',filter='all',intakeFilter='all',localOnly=false;
const demoPeople=[['Aarav','Sharma',0,'October','Under Assessment'],['Priya','Patel',1,'July','Registration Fee Pending'],['Sanjay','Rai',2,'October','Offer Letter Released'],['Ananya','Mehta',0,'July','Enrolled'],['Rohan','Shah',1,'October','Draft'],['Aditi','Shrestha',2,'July','Payment Plan Issued']];
const demo=demoPeople.map((p,i)=>({id:'RCL-DEMO-10'+(21+i),firstName:p[0],lastName:p[1],programme:programmes[p[2]],intake:p[3],status:p[4],channel:'B2B',agency:'Horizon Education · demo agency',recruiter:'Neha Kapoor · demo recruiter',country:i===2||i===5?'Nepal':'India',created:new Date(Date.now()-(7-i)*86400000).toISOString(),demo:true,docs:{},history:[{action:'Sample application received',at:new Date(Date.now()-7*86400000).toISOString(),actor:'Demo agency'},{action:p[4],at:new Date(Date.now()-i*86400000).toISOString(),actor:'Demo admissions team'}],remarks:i===0?'Academic documents are awaiting admissions verification.':i===1?'Eligible for the selected programme. Registration fee instructions will be provided by the recruiter.':'No outstanding remarks.'}));
function connect(){return new Promise((resolve,reject)=>{const r=indexedDB.open('rcl-portal-preview-v1',1);r.onupgradeneeded=()=>{for(const s of ['applications','files','messages'])r.result.createObjectStore(s,{keyPath:'id'})};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
function readAll(s){return new Promise((res,rej)=>{const r=db.transaction(s).objectStore(s).getAll();r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
function put(s,v){return new Promise((res,rej)=>{const tx=db.transaction(s,'readwrite');tx.objectStore(s).put(v);tx.oncomplete=()=>res(v);tx.onerror=()=>rej(tx.error);tx.onabort=()=>rej(tx.error)})}
function remove(s,id){return new Promise((res,rej)=>{const tx=db.transaction(s,'readwrite');tx.objectStore(s).delete(id);tx.oncomplete=res;tx.onerror=()=>rej(tx.error)})}
function get(s,id){return new Promise((res,rej)=>{const r=db.transaction(s).objectStore(s).get(id);r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
async function refresh(){records=await readAll('applications');messages=await readAll('messages')}
function apps(){return [...records.filter(a=>a.channel==='B2B'),...(localOnly?[]:demo)].sort((a,b)=>b.created.localeCompare(a.created))}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',4500)}
function go(v){view=v;search='';filter='all';render();window.scrollTo(0,0)}
function brand(){return '<div class="brand"><span class="brand-mark">R</span><div>REGENT<small>COLLEGE LONDON</small></div></div>'}
function nav(){return [['overview','grid','Overview'],['applications','file','Applications'],['documents','folder','Documents'],['messages','chat','Messages'],['notifications','bell','Notifications']].map(([v,i,l])=>'<button data-nav="'+v+'" class="'+(view===v?'active':'')+'">'+icon(i)+l+(v==='applications'?'<span class="count">'+apps().length+'</span>':'')+'</button>').join('')}
function preview(){return '<div class="preview"><strong>Interactive preview</strong> · Sample records are labelled. Your test entries and files stay in this browser. No live login, CRM submission, payment, or email delivery. Use test data only.</div>'}
function shell(body){root.innerHTML='<div class="layout"><aside class="sidebar">'+brand()+'<div class="portal-label">Partner workspace</div><nav class="nav" aria-label="Main navigation">'+nav()+'</nav><div class="sidebar-bottom"><div class="help-card">'+icon('help')+'<h3 style="margin-top:12px">A little guidance?</h3><p>Everything you need to submit a complete application.</p><button class="text-btn" data-nav="guide">View application guide '+icon('arrow')+'</button></div><div class="agent"><div class="avatar">HE</div><div><b style="font-size:11px">Horizon Education</b><small>Demonstration agency</small></div></div></div></aside><div><header class="topbar"><div class="breadcrumb">Partner portal &nbsp; / &nbsp; <b>'+esc(view==='detail'?'Application details':view.charAt(0).toUpperCase()+view.slice(1))+'</b></div><div class="top-actions"><span class="badge green">Mumbai campus</span><button class="text-btn" data-action="direct">Direct student form ↗</button><button class="round-btn" data-nav="notifications" aria-label="Notifications">'+icon('bell')+'</button><button class="round-btn" data-action="signout" aria-label="Leave agent preview">'+icon('logout')+'</button></div></header><main class="workspace">'+preview()+body+'<footer class="bottom-note"><span>RCL Mumbai · Application portal</span><span>India & Nepal &nbsp; · &nbsp; July / October intakes</span></footer></main></div></div>';bind()}
function heading(title,sub,button=true){return '<div class="page-heading"><div><div class="eyebrow">Admissions, made connected</div><h1>'+title+'</h1><p class="subtitle">'+sub+'</p></div>'+(button?'<button class="btn" data-action="new">'+icon('plus')+' New application</button>':'')+'</div>'}
function rows(list){return list.map(a=>'<tr><td><div class="student-cell"><div class="avatar">'+esc(initials(a))+'</div><div><button class="student-name" data-open="'+a.id+'">'+esc(name(a))+'</button><span class="student-meta">'+esc(a.id)+(a.demo?' · Sample':' · Browser-local')+'</span></div></div></td><td>'+esc(short(a.programme||'Not selected'))+'<span class="student-meta">'+esc(a.intake||'Intake not selected')+' · Mumbai</span></td><td>'+badge(a.status)+'</td><td><button class="text-btn" data-open="'+a.id+'" aria-label="Open '+esc(name(a))+'">'+icon('arrow')+'</button></td></tr>').join('')}
function table(list){return list.length?'<div class="table-wrap"><table><thead><tr><th>STUDENT</th><th>PROGRAMME / INTAKE</th><th>APPLICATION STATUS</th><th><span aria-label="Actions"></span></th></tr></thead><tbody>'+rows(list)+'</tbody></table></div>':'<div class="empty"><h3>No applications found</h3><p>Start a new application or adjust your filters.</p></div>'}
function overview(){const list=apps(),drafts=list.filter(a=>a.status==='Draft'),pending=list.filter(a=>/Pending/.test(a.status));return heading('Your next intake starts here.','A clear view of your students, applications, and next steps.')+'<section class="hero"><div class="hero-text"><div class="eyebrow">RCL Mumbai · Undergraduate admissions</div><h2>Big ambitions.<br>A brighter future in Mumbai.</h2><p>Three programmes. One connected application journey.<br>Supporting students from India and Nepal.</p></div><div class="hero-intakes"><div class="intake-tile"><b>July</b><span>INTAKE</span></div><div class="intake-tile"><b>Oct</b><span>INTAKE</span></div></div></section><div class="stats">'+[['Total applications',list.length,'file','Across both intakes'],['Action required',drafts.length+pending.length,'clock','Drafts and pending actions'],['Offers released',list.filter(a=>stages.indexOf(a.status)>=5).length,'cap','Including later stages'],['Students enrolled',list.filter(a=>a.status==='Enrolled').length,'check','Completed application journey']].map(([l,n,i,f])=>'<div class="stat"><div class="stat-top">'+l+'<span class="stat-icon">'+icon(i)+'</span></div><div class="stat-number">'+n.toString().padStart(2,'0')+'</div><div class="stat-foot">'+f+'</div></div>').join('')+'</div><div class="split"><div><section class="card"><div class="card-header"><h2>Recent applications</h2><button class="text-btn" data-nav="applications">View all '+icon('arrow')+'</button></div>'+table(list.slice(0,5))+'<div class="card-footer">Sample and browser-local records · No CRM connection</div></section><section class="card"><div class="card-header"><h2>A clear path to enrolment</h2><span class="badge gray">Your application journey</span></div><div class="pad" style="padding-top:0"><div class="status-track">'+['Application','Assessment','Registration fee','Conditional offer','Payment plan'].map((s,i)=>'<div class="'+(i===0?'done':'')+'">'+String(i+1).padStart(2,'0')+'<br>'+s+'</div>').join('')+'</div></div></section></div><div class="right-stack"><section class="card"><div class="card-header"><h2>Needs your attention</h2><span class="count">'+(drafts.length+pending.length)+'</span></div>'+[...pending,...drafts].slice(0,3).map(a=>'<div class="action-item"><div class="action-icon">'+icon('clock')+'</div><div><b>'+esc(name(a))+'</b><p>'+esc(a.status==='Draft'?'Complete the application and required documents.':a.status+'. Review the next steps with your recruiter.')+'</p><button class="text-btn" data-open="'+a.id+'">Review application →</button></div></div>').join('')+(!(drafts.length+pending.length)?'<div class="pad subtitle">You’re all caught up.</div>':'')+'</section><section class="card recruiter-card"><h2 style="font-size:14px">Your recruitment partner</h2><div class="recruiter-person"><div class="avatar">NK</div><div><b style="font-size:12px">Neha Kapoor</b><p>Assigned recruiter · sample</p></div></div><p class="subtitle" style="line-height:1.8;margin-bottom:18px">Questions about an application?<br>Keep the conversation in one place.</p><button class="btn secondary wide" data-nav="messages">'+icon('chat')+' Open messages</button></section></div></div>'}
function applications(){return heading('Applications','Every student. Every stage. All in one place.')+'<section class="card"><div class="card-header"><h2>Application register</h2><button class="btn secondary small" data-action="export">'+icon('down')+' Export CSV</button></div><div class="toolbar"><div class="search">'+icon('search')+'<input id="search" aria-label="Search applications" placeholder="Search student name or application ID" value="'+esc(search)+'"></div><select id="filter" aria-label="Filter application status"><option value="all">All statuses</option>'+['Draft',...stages].map(s=>'<option '+(filter===s?'selected':'')+'>'+s+'</option>').join('')+'</select><select id="intake-filter" aria-label="Filter intake"><option value="all">All intakes</option>'+intakeOptions.map(s=>'<option '+(intakeFilter===s?'selected':'')+'>'+s+'</option>').join('')+'</select></div><div id="results">'+table(filtered())+'</div><div class="card-footer"><label class="check" style="margin:0"><input type="checkbox" id="local-only" '+(localOnly?'checked':'')+'> Show only my browser-local applications</label></div></section>'}
function filtered(){return apps().filter(a=>(name(a)+' '+a.id).toLowerCase().includes(search.toLowerCase())&&(filter==='all'||a.status===filter)&&(intakeFilter==='all'||a.intake===intakeFilter))}
function docsPage(){const docs=apps().flatMap(a=>Object.entries(a.docs||{}).map(([type,d])=>({a,type,d})));return heading('Document centre','Application evidence, organised by student.',false)+'<section class="card"><div class="card-header"><h2>Uploaded documents</h2><span class="badge gray">'+docs.length+' files</span></div><div class="pad">'+(docs.length?docs.map(({a,type,d})=>'<div class="doc-row">'+icon('file')+'<div class="file-info"><b>'+esc(type)+'</b><p>'+esc(name(a))+' · '+esc(d.name)+' · v'+d.version+'</p><span class="badge gold">Awaiting verification</span></div><button class="btn secondary small" data-file="'+d.id+'">Download</button><button class="text-btn" data-open="'+a.id+'">View →</button></div>').join(''):'<div class="empty">'+icon('folder')+'<h3>Your documents will appear here</h3><p>Upload evidence while completing a new application.<br>Sample records do not contain personal documents.</p><button class="btn" data-action="new">Start an application</button></div>')+'</div></section>'}
function detail(){const a=selected,ix=stages.indexOf(a.status);const content=detailTab==='overview'?'<div class="kv">'+[['Application ID',a.id],['Source',a.channel+' · '+(a.demo?'sample':'browser-local')],['Programme',a.programme||'Not selected'],['Campus / intake','RCL Mumbai / '+(a.intake||'Not selected')],['Country',a.country||'Not entered'],['Assigned recruiter',a.recruiter||'Agency account owner · integration pending'],['Agency',a.agency||'Horizon Education · demo agency'],['Created',fmt(a.created)]].map(([l,v])=>'<div><small>'+l+'</small><p>'+esc(v)+'</p></div>').join('')+'</div><div class="note"><strong>Application remarks</strong><br>'+esc(a.remarks||'Your application has not yet been reviewed by an admissions team.')+'</div>':detailTab==='documents'?'<p class="subtitle">Uploads remain unverified until checked by Admissions.</p>'+requirements(a).map(t=>{const d=a.docs?.[t];return '<div class="doc-row">'+icon('file')+'<div class="file-info"><b>'+esc(t)+'</b><p>'+esc(d?d.name+' · Version '+d.version:'No file in this preview')+'</p>'+badge(d?'Awaiting verification':'Not uploaded')+'</div>'+(d?'<button class="btn secondary small" data-file="'+d.id+'">Download</button>':'')+'</div>'}).join(''):detailTab==='offers'?'<h3>Conditional offer letter</h3><p class="subtitle">Released by Admissions after registration payment is confirmed.</p><div class="note">'+(ix>=5?'This sample application has a conditional offer.':'No offer letter has been released.')+'</div>'+(a.demo&&ix>=5?'<button class="btn secondary" data-download="offer">'+icon('down')+' Download sample offer</button>':'')+'<h3 style="margin-top:30px">Payment plan</h3><p class="subtitle">Agreed with the assigned recruiter after the conditional offer.</p><div class="note">'+(ix>=7?'Sample plan status: issued. Financial terms are not configured.':'No payment plan has been issued.')+'</div>'+(a.demo&&ix>=7?'<button class="btn secondary" data-download="plan">'+icon('down')+' Download sample plan</button>':''): '<ol class="timeline">'+[...(a.history||[])].reverse().map(h=>'<li><b>'+esc(h.action)+'</b><p>'+esc(h.actor)+' · '+fmt(h.at)+' '+new Date(h.at).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})+'</p></li>').join('')+'</ol>';return '<button class="text-btn" data-nav="applications" style="margin-bottom:20px">'+icon('back')+' Back to applications</button>'+heading(esc(name(a)),esc(a.id)+(a.demo?' · Sample application':' · Browser-local application'),false)+'<div class="page-heading">'+badge(a.status)+(a.status==='Draft'&&!a.demo?'<button class="btn" data-action="resume">Continue draft '+icon('arrow')+'</button>':'')+'</div><div class="status-track">'+stages.map((s,i)=>'<div class="'+(i<=ix?'done':'')+'">'+(i+1)+'. '+s+'</div>').join('')+'</div><section class="card"><div class="tabs">'+[['overview','Overview'],['documents','Documents'],['offers','Offers & payment plan'],['history','Activity history']].map(([k,l])=>'<button data-tab="'+k+'" class="'+(detailTab===k?'active':'')+'">'+l+'</button>').join('')+'</div><div class="pad">'+content+'</div></section>'}
function messagePage(){return heading('Messages','Keep application conversations together.',false)+'<section class="card"><div class="card-header"><h2>Neha Kapoor <span class="student-meta">Sample agency recruiter</span></h2><span class="badge gray">Local draft conversation</span></div><div class="pad"><div class="note">Messages saved here are preview drafts only. They are not delivered to a recruiter.</div>'+messages.map(m=>'<div class="message mine"><small>'+esc(m.application||'General enquiry')+'</small><p>'+esc(m.text)+'</p><small>Saved locally · '+fmt(m.created)+'</small></div>').join('')+'<form id="message-form"><label class="field"><span>Related application</span><select name="application"><option value="">General enquiry</option>'+apps().map(a=>'<option value="'+a.id+'">'+esc(name(a))+' · '+a.id+'</option>').join('')+'</select></label><label class="field"><span>Message</span><textarea name="text" required maxlength="2000" placeholder="Write your question or application update…"></textarea></label><button class="btn" type="submit">Save message draft '+icon('arrow')+'</button></form></div></section>'}
function notices(){const items=apps().filter(a=>a.status!=='Draft');return heading('Notifications','Updates linked to your applications.',false)+'<section class="card"><div class="card-header"><h2>Application updates</h2><span class="badge gray">Preview activity</span></div>'+items.map(a=>'<div class="action-item"><div class="action-icon">'+icon('bell')+'</div><div><b>'+esc(name(a))+' · '+esc(a.status)+'</b><p>'+fmt(a.created)+' · '+(a.demo?'Sample update':'Saved in this browser')+'</p><button class="text-btn" data-open="'+a.id+'">View application →</button></div></div>').join('')+(!items.length?'<div class="empty">No application updates yet.</div>':'')+'</section>'}
function guide(){return heading('A complete application, first time.','A short guide for RCL Mumbai recruitment partners.',false)+'<section class="card pad"><h2>Before you begin</h2><p>Applications are for RCL Mumbai, recruiting from India and Nepal. Applicants must be 18 or older. Choose BSc Business Management, BSc Computer Science, or BEng Software Engineering, with a July or October intake.</p><h3>Prepare the student’s evidence</h3><p>The current preview checklist requires a passport, academic certificates, and transcripts / mark sheets. English evidence, CV, experience letter, and a statement of purpose are conditional. Programme-specific rules still need Admissions approval. Upload PDF, JPG, or PNG files up to 10 MB each.</p><h3>What happens after submission?</h3><p>Agency submissions are intended to become B2B leads linked to the agency’s recruiter. Direct submissions are intended to go to the Direct Team Lead for assignment. Admissions checks eligibility and documents. Registration payment must be verified before a conditional offer is released. The recruiter then records the agreed payment plan.</p><h3>Direct applicants do not need an account</h3><p>They submit once through the website form. An acknowledgement email and recruiter communication will follow when the email and CRM integrations are connected.</p><div class="note"><b>Preview configuration</b><br>July / October are confirmed intake months. Intake years and deadlines, tuition and registration fees, programme-specific document rules, agency accounts, CRM endpoints, and approved communications need configuration before live use.</div><button class="btn" data-action="new">Start an application '+icon('arrow')+'</button></section>'}
function newForm(channel){form={id:'RCL-TEST-'+crypto.randomUUID().slice(0,8).toUpperCase(),channel,status:'Draft',created:new Date().toISOString(),docs:{},history:[],campus:'RCL Mumbai',country:'India',english:'',experience:'',sop:'',marketing:false};step=0;errors=[];savedAt='';if(channel==='B2B'){view='wizard';render()}else{location.hash='apply';render()}}
function field(k,label,type='text',options,help=''){const val=form[k]||'';return '<label class="field"><span>'+label+' <span style="color:#839971">*</span></span>'+(options?'<select name="'+k+'" required><option value="">Select an option</option>'+options.map(v=>'<option value="'+esc(v)+'" '+(val===v?'selected':'')+'>'+esc(v)+'</option>').join('')+'</select>':'<input name="'+k+'" type="'+type+'" value="'+esc(val)+'" required '+(type==='date'?'max="'+new Date().toISOString().slice(0,10)+'"':'')+' maxlength="250">')+(help?'<small>'+help+'</small>':'')+'</label>'}
function yesNo(k,l,help=''){return '<label class="field"><span>'+l+' *</span><select name="'+k+'" required><option value="">Select an option</option><option value="no" '+(form[k]==='no'?'selected':'')+'>No</option><option value="yes" '+(form[k]==='yes'?'selected':'')+'>Yes</option></select>'+(help?'<small>'+help+'</small>':'')+'</label>'}
function wizard(){const titles=['Personal details','Course selection','Education','Documents','Review & submit'];let content='';
if(step===0)content='<div class="grid2">'+field('firstName','First name')+field('lastName','Last name')+field('email','Email address','email')+field('phone','Phone number','tel')+field('dob','Date of birth','date',null,'Applicants must be 18 or older.')+field('country','Country of residence','text',['India','Nepal'])+field('nationality','Nationality')+field('address','Residential address')+yesNo('conviction','Any criminal convictions?','Only a yes/no declaration is collected. Admissions will review disclosures.')+'</div>';
if(step===1)content='<div class="note">Campus: <strong>RCL Mumbai</strong> · Undergraduate programmes</div>'+field('programme','Choose your programme','text',programmes)+field('intake','Preferred intake','text',intakeOptions,'Intake year and application deadlines will be confirmed by Admissions.')+'<p class="subtitle">Your personal profile can support more than one application. Each programme application has its own reference and status.</p>';
if(step===2)content='<div class="grid2">'+field('qualification','Highest qualification')+field('board','Board / university')+field('year','Year of completion','number')+field('grade','Percentage / grade')+yesNo('english','English language evidence applicable?')+yesNo('experience','Do you have work experience?')+yesNo('sop','Statement of purpose applicable?','Provisional checklist: programme rules must be confirmed by Admissions.')+'</div><label class="field"><span>Education gaps or prior learning (optional)</span><textarea name="gaps" maxlength="2000" placeholder="Add context for the Admissions team.">'+esc(form.gaps||'')+'</textarea></label>';
if(step===3)content='<p class="subtitle">Required files must be uploaded before submission. PDF, JPG or PNG · maximum 10 MB per file.</p><div class="note">Use test documents only. Files are saved in this browser, not sent to RCL. Programme-specific requirements are provisional.</div>'+requirements(form).map((t,i)=>{const d=form.docs[t];return '<div class="doc-row">'+icon('file')+'<div class="file-info"><b>'+esc(t)+' *</b><p>'+esc(d?d.name+' · '+(d.size/1024).toFixed(0)+' KB · v'+d.version:'Required before submission')+'</p>'+(d?badge('Awaiting verification'):'')+'</div><label class="upload">'+(d?'Replace file':'Choose file')+'<input type="file" data-upload="'+esc(t)+'" accept=".pdf,.jpg,.jpeg,.png" aria-label="Upload '+esc(t)+'"></label>'+(d?'<button class="text-btn" data-remove-doc="'+esc(t)+'" aria-label="Remove '+esc(t)+'">Remove</button>':'')+'</div>'}).join('');
if(step===4)content='<div class="kv">'+[['Applicant',name(form)],['Email',form.email],['Date of birth',form.dob],['Country',form.country],['Programme',form.programme],['Campus / intake','RCL Mumbai / '+form.intake],['Qualification',form.qualification],['Documents',requirements(form).filter(t=>form.docs[t]).length+' / '+requirements(form).length+' uploaded']].map(([l,v])=>'<div><small>'+l+'</small><p>'+esc(v)+'</p></div>').join('')+'</div><div class="note">Please check your details before submitting. Direct applicants do not get a student login. In the live service, further communication will be handled by the assigned recruiter.</div>'+check('declaration','I confirm that the information supplied is accurate and the applicant is aged 18 or older.')+check('privacy','I understand this is a browser-local preview and I am using test data only.')+(form.channel==='B2B'?check('authority','I am authorised by this student to submit their application and supporting documents.'):'')+check('marketing','Optional: I agree to receive course information and marketing communications.')+'<p class="subtitle">Marketing consent is optional and does not affect submission. RCL’s approved privacy notice must be added before this form goes live.</p>';
return '<div class="wizard">'+(form.channel==='B2B'?'<button class="text-btn" data-action="leave-form">'+icon('back')+' Save and return to applications</button>':'')+'<div class="stepper" aria-label="Application progress">'+titles.map((t,i)=>'<div class="step '+(i===step?'active':i<step?'done':'')+'" '+(i===step?'aria-current="step"':'')+'>'+String(i+1).padStart(2,'0')+' · '+t+'</div>').join('')+'</div><section class="card"><div class="card-header"><div><div class="eyebrow">Step '+(step+1)+' of 5</div><h2>'+titles[step]+'</h2></div><span class="badge gray">'+(form.channel==='B2B'?'Agent application':'Direct application')+'</span></div><form id="application-form" novalidate><div class="pad" style="padding-top:6px">'+(errors.length?'<div class="error" role="alert" tabindex="-1">'+errors.map(esc).join('<br>')+'</div>':'')+content+'</div><div class="wizard-footer"><button type="button" class="btn secondary" data-action="back" '+(step===0?'disabled':'')+'>'+icon('back')+' Back</button><div style="display:flex;align-items:center;gap:10px">'+(form.channel==='B2B'?'<button type="button" class="text-btn" data-action="save">Save draft</button>':'')+'<button class="btn" type="submit">'+(step===4?'Submit test application':'Continue')+' '+icon('arrow')+'</button></div></div></form></section><p class="subtitle" style="text-align:center">'+(savedAt?'Draft saved locally at '+savedAt:'Your progress is kept while moving between steps.')+'</p></div>'}
function check(k,l){return '<label class="check"><input type="checkbox" name="'+k+'" '+(form[k]?'checked':'')+'>'+l+'</label>'}
function capture(){const f=$('#application-form');if(!f)return;for(const el of f.elements)if(el.name)form[el.name]=el.type==='checkbox'?el.checked:el.value}
async function saveDraft(){capture();if(form.channel!=='B2B')return;await put('applications',structuredClone(form));await refresh();savedAt=new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})}
function renderPublic(){root.innerHTML='<header class="public-top">'+brand()+'<button class="text-btn" data-action="partner">Agent portal '+icon('arrow')+'</button></header><main class="public-main">'+preview()+'<div class="public-heading"><div class="eyebrow">RCL Mumbai · July & October</div><h1>Your future starts with an application.</h1><p>Apply to one of our three undergraduate programmes. No student account needed.</p></div>'+wizard()+'</main>';bind()}
function login(){root.innerHTML='<header class="public-top">'+brand()+'<button class="text-btn" data-action="direct">Apply as a student →</button></header><main class="public-main">'+preview()+'<section class="card login"><div class="eyebrow">Recruitment partners</div><h1>Your students. One workspace.</h1><p>Manage applications, documents, and admission updates for your agency.</p><div class="note">Agency authentication is not connected in this version. Explore a clearly labelled demo workspace with sample records.</div><button class="btn wide" data-action="enter">Enter agent preview '+icon('arrow')+'</button><p>Production access will use individual agency credentials and server-enforced access to the agency’s own students.</p></section></main>';bind()}
function render(){if(location.hash==='#apply'){if(!form||form.channel!=='Direct')newForm('Direct');else renderPublic();return}if(location.hash==='#login'){login();return}if(view==='wizard'&&form?.channel==='B2B'){shell(wizard());return}shell(view==='overview'?overview():view==='applications'?applications():view==='documents'?docsPage():view==='detail'?detail():view==='messages'?messagePage():view==='notifications'?notices():guide())}
function openApp(id){selected=apps().find(a=>a.id===id);if(!selected)return;detailTab='overview';go('detail')}
function download(content,filename,type='text/plain'){const u=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=u;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
async function downloadFile(id){const f=await get('files',id);if(!f){toast('File is not available in this browser.');return}download(f.blob,f.name,f.blob.type)}
async function upload(type,file){if(!file)return;if(!safeFile(file)){toast('Choose a non-empty PDF, JPG or PNG file, up to 10 MB.');return}const bytes=new Uint8Array(await file.slice(0,8).arrayBuffer());const valid=(/\.pdf$/i.test(file.name)&&String.fromCharCode(...bytes.slice(0,5))==='%PDF-')||(/\.jpe?g$/i.test(file.name)&&bytes[0]===255&&bytes[1]===216&&bytes[2]===255)||(/\.png$/i.test(file.name)&&bytes[0]===137&&bytes[1]===80&&bytes[2]===78&&bytes[3]===71);if(!valid){toast('The file content does not match a supported PDF or image.');return}const old=form.docs[type],id=crypto.randomUUID();await put('files',{id,name:file.name,blob:file,application:form.id});form.docs[type]={id,name:file.name,size:file.size,version:(old?.version||0)+1,uploaded:new Date().toISOString(),previous:[...(old?.previous||[]),...(old?[{id:old.id,name:old.name,version:old.version}]:[])]};form.history.push({action:type+' uploaded (v'+form.docs[type].version+')',actor:form.channel==='B2B'?'Preview agency':'Direct applicant',at:new Date().toISOString()});if(form.channel==='B2B')await saveDraft();errors=[];render();toast('File stored in this browser.')}
async function submitStep(e){e.preventDefault();capture();errors=validate(form,step);if(errors.length){render();$('.error')?.focus();return}if(step<4){if(form.channel==='B2B')await saveDraft();step++;errors=[];render();window.scrollTo(0,0);return}errors=allErrors(form);if(errors.length){render();$('.error')?.focus();return}
const submitButton=$('#application-form button[type=submit]');submitButton.disabled=true;
try{for(const type of requirements(form)){if(!await get('files',form.docs[type].id))throw new Error('A required file is missing from browser storage. Return to Documents and upload it again.')}const duplicate=records.find(a=>a.id!==form.id&&a.status!=='Draft'&&a.email?.toLowerCase()===form.email.toLowerCase()&&a.programme===form.programme&&a.intake===form.intake&&a.channel===form.channel);if(duplicate)throw new Error('A test application for this email, programme and intake already exists: '+duplicate.id);
form.status='New Application';form.submitted=new Date().toISOString();form.routing=form.channel==='B2B'?'Agency account owner / recruiter':'Direct Team Lead';form.history.push({action:'Test application submitted; '+form.channel+' routing queued (integration pending)',actor:form.channel==='B2B'?'Preview agency':'Direct applicant',at:form.submitted});await put('applications',structuredClone(form));await refresh();const submitted=structuredClone(form);form=null;if(submitted.channel==='B2B'){selected=submitted;detailTab='overview';view='detail';render();toast('Test application saved. No data has been sent to RCL.')}else showSuccess(submitted)}catch(err){errors=[err.message||'Unable to save. Check available browser storage and retry.'];if(form)form.status='Draft';render()}}
function showSuccess(a){root.innerHTML='<header class="public-top">'+brand()+'</header><main class="public-main">'+preview()+'<section class="card success"><div class="success-icon">'+icon('check')+'</div><div class="eyebrow">Test submission complete</div><h1>Your application has been saved locally.</h1><p>Thank you, '+esc(a.firstName)+'. Your preview reference is:</p><code>'+a.id+'</code><p>'+esc(a.programme)+'<br>RCL Mumbai · '+esc(a.intake)+' intake</p><div class="note">No application was sent to RCL and no acknowledgement email was sent. In the live service, the Direct Team Lead will assign a recruiter to follow up.</div><button class="btn" id="receipt">Download test receipt '+icon('down')+'</button><button class="text-btn" data-action="partner" style="display:block;margin:24px auto 0">Return to agent preview</button></section></main>';bind();$('#receipt').onclick=()=>download('RCL MUMBAI — TEST RECEIPT\nNot a submitted admissions application\n\nReference: '+a.id+'\nProgramme: '+a.programme+'\nIntake: '+a.intake+'\nSaved: '+fmt(a.submitted)+'\n\nNo email or CRM delivery.','test-receipt-'+a.id+'.txt')}
function modal(title,body,action){const wrap=document.createElement('div');wrap.className='modal-wrap';wrap.innerHTML='<section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><h2 id="modal-title">'+title+'</h2><p>'+body+'</p><div class="modal-actions"><button class="btn secondary" id="cancel-modal">Cancel</button><button class="btn" id="confirm-modal">Continue</button></div></section>';root.append(wrap);const before=document.activeElement;$('#cancel-modal').onclick=()=>{wrap.remove();before?.focus()};$('#confirm-modal').onclick=()=>{wrap.remove();action()};wrap.onkeydown=e=>{if(e.key==='Escape')$('#cancel-modal').click();if(e.key==='Tab'){e.preventDefault();(document.activeElement.id==='cancel-modal'?$('#confirm-modal'):$('#cancel-modal')).focus()}};$('#cancel-modal').focus()}
function bind(){document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>go(b.dataset.nav));document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openApp(b.dataset.open));document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{detailTab=b.dataset.tab;render()});document.querySelectorAll('[data-file]').forEach(b=>b.onclick=()=>downloadFile(b.dataset.file).catch(()=>toast('Unable to read file.')));document.querySelectorAll('[data-upload]').forEach(el=>el.onchange=()=>upload(el.dataset.upload,el.files[0]).catch(()=>toast('Unable to save file. Browser storage may be full.')));document.querySelectorAll('[data-remove-doc]').forEach(b=>b.onclick=async()=>{const t=b.dataset.removeDoc;delete form.docs[t];if(form.channel==='B2B')await saveDraft();render()});document.querySelectorAll('[data-download]').forEach(b=>b.onclick=()=>download('RCL MUMBAI — SAMPLE ONLY\nNOT AN OFFICIAL ADMISSION OR FINANCIAL DOCUMENT\n\n'+(b.dataset.download==='offer'?'CONDITIONAL OFFER PREVIEW':'PAYMENT PLAN PREVIEW')+'\nStudent: '+name(selected)+'\nProgramme: '+selected.programme+'\nIntake: '+selected.intake+'\n\nNo fee values, conditions or payment schedule have been approved.\nThis file demonstrates the download interaction only.','sample-'+b.dataset.download+'-'+selected.id+'.txt'));
document.querySelectorAll('[data-action]').forEach(b=>b.onclick=async()=>{try{switch(b.dataset.action){case'new':newForm('B2B');break;case'direct':if(form?.channel==='B2B')await saveDraft();form=null;location.hash='apply';render();break;case'partner':if(form?.channel==='Direct'){modal('Leave the test application?','Your unsubmitted direct application will be discarded from this form.',()=>{form=null;location.hash='';view='overview';render()})}else{location.hash='';view='overview';render()}break;case'enter':agentSession=true;sessionStorage.setItem('rcl-agent-preview','yes');location.hash='';view='overview';render();break;case'signout':sessionStorage.removeItem('rcl-agent-preview');agentSession=false;location.hash='login';render();break;case'back':capture();step=Math.max(0,step-1);errors=[];render();break;case'save':await saveDraft();toast('Draft saved in this browser.');render();break;case'leave-form':await saveDraft();form=null;go('applications');break;case'resume':form=structuredClone(selected);step=0;errors=[];view='wizard';render();break;case'export':download([['Reference','Student','Programme','Intake','Status','Record type'],...filtered().map(a=>[a.id,name(a),a.programme,a.intake,a.status,a.demo?'Sample':'Browser-local'])].map(r=>r.map(csvCell).join(',')).join('\r\n'),'rcl-applications-preview.csv','text/csv;charset=utf-8');break}}catch(e){toast('Could not save your change. Check browser storage and retry.')}});
$('#application-form')?.addEventListener('submit',e=>submitStep(e).catch(()=>toast('Unable to save. Please retry.')));
const updateResults=()=>{ $('#results').innerHTML=table(filtered());$('#results').querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openApp(b.dataset.open))};
if($('#search'))$('#search').oninput=e=>{search=e.target.value;updateResults()};
if($('#filter'))$('#filter').onchange=e=>{filter=e.target.value;updateResults()};
if($('#intake-filter'))$('#intake-filter').onchange=e=>{intakeFilter=e.target.value;updateResults()};
if($('#local-only'))$('#local-only').onchange=e=>{localOnly=e.target.checked;updateResults()};
$('#message-form')?.addEventListener('submit',async e=>{e.preventDefault();const data=new FormData(e.target),text=String(data.get('text')||'').trim();if(!text){toast('Enter a message first.');return}try{await put('messages',{id:crypto.randomUUID(),text,application:data.get('application'),created:new Date().toISOString()});await refresh();render();toast('Message draft saved locally; not delivered.')}catch{toast('Unable to save message.')}});
}
window.addEventListener('hashchange',render);
try{db=await connect();await refresh();render()}catch{root.innerHTML='<main class="public-main"><section class="card pad"><h1>Browser storage is unavailable</h1><p>This preview requires IndexedDB for test applications and files. Open it in a normal browser window with site storage enabled.</p></section></main>'}
